const tearChoice=setup({begun:true,phase:'studentRoom',hidden:true,coverClosed:true,destroyed:false,phoneOpen:false});tearChoice.run("hot('bin')");assert(screenHTML(tearChoice).includes('撕碎它'));assert(screenHTML(tearChoice).includes('不做任何事'));assert(screenHTML(tearChoice).includes('vn-topic-options'));assert.equal(tearChoice.dom('#shen-phone-launcher').hidden,true);tearChoice.run("act('leavecopy')");assert.equal(tearChoice.run('state.destroyed'),false);assert(screenHTML(tearChoice).includes('你沒有對謄本做任何事。'));assert(!screenHTML(tearChoice).includes('data-act="return2018"'));tearChoice.run("act('return2018')");assert.equal(tearChoice.run('state.phase'),'studentRoom');tearChoice.run("act('dismissscene');hot('bin');act('destroy')");assert.equal(tearChoice.run('state.destroyed'),true);assert(screenHTML(tearChoice).includes('data-act="return2018"'));tearChoice.run("act('return2018')");assert.equal(tearChoice.run('state.vnKey'),'memory');console.log('PASS tear choice: deferring leaves the copy intact and returns to exploration; reconsidering and tearing unlocks the original continuation.');

const hideChoice=setup({begun:true,phase:'studentRoom',hidden:false,coverClosed:false,destroyed:true,phoneOpen:false});hideChoice.run("hot('rail');act('considerhide')");assert(screenHTML(hideChoice).includes('藏進去'));assert(screenHTML(hideChoice).includes('不做任何事'));assert.equal(hideChoice.dom('#shen-phone-launcher').hidden,true);hideChoice.run("act('leavehide')");assert.equal(hideChoice.run('state.hidden'),false);assert(screenHTML(hideChoice).includes('紙仍留在你手中'));hideChoice.run("act('return2018');act('closecover')");assert.equal(hideChoice.run('state.phase'),'studentRoom');assert.equal(hideChoice.run('state.coverClosed'),false);hideChoice.run("act('dismissscene');hot('rail');act('considerhide');act('hide')");assert.equal(hideChoice.run('state.hidden'),true);assert(screenHTML(hideChoice).includes('data-act="closecover"'));assert(!screenHTML(hideChoice).includes('data-act="return2018"'));hideChoice.run("act('closecover')");assert(screenHTML(hideChoice).includes('data-act="return2018"'));hideChoice.run("act('return2018')");assert.equal(hideChoice.run('state.vnKey'),'memory');console.log('PASS hide choice: deferring keeps the copy in hand and the cap open; later confirmation, cap closure and destroyed first copy unlock continuation.');
